
/* Generated by Interface Builder */

#import <appkit/Application.h>
#import <appkit/View.h>
#import <appkit/Window.h>

#import "ArabesqueView.h"

#import "Controller.h"

@implementation Controller


void sendDisplayProc(DPSTimedEntry teNumber,double now,void *theView)
	{
	if([(id)theView respondsTo:@selector(oneStep)])
		{
		[(id)theView lockFocus];
		[(id)theView oneStep];
		[(id)theView unlockFocus];
		[[(id)theView window] flushWindow];
		}
	[(id)theView display];
	}


- start:sender
	{
	sendDisplayTE=DPSAddTimedEntry(0.3,sendDisplayProc,
									(void *)kView,NX_BASETHRESHOLD);
    return self;
	}


- stop:sender
	{
	DPSRemoveTimedEntry(sendDisplayTE);
    return self;
	}


- appDidInit:sender;
	{
	if([kView respondsTo:@selector(windowTitle)])
		[[kView window] setTitle:[kView windowTitle]];
	return [self start:sender];
	}


- appWillTerminate:sender;
	{
	return [self stop:sender];
	}
	
@end
